using Inquiry.Oracle.Tests.Fixtures;
using Inquiry.Tests.UpsertMatchOn;

namespace Inquiry.Oracle.Tests;

/// <summary>#614: upserts matched on a unique natural key against a live Oracle engine.</summary>
[Collection(OracleCollection.Name)]
public sealed class UpsertMatchOnIntegrationTests
{
    private const string Ddl =
        "CREATE TABLE MatchPref (Id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, MemberKey NUMBER(10) NOT NULL, TypeCode VARCHAR2(20) NOT NULL, Weight NUMBER(10) NOT NULL, CONSTRAINT UX_MatchPref UNIQUE (MemberKey, TypeCode)); CREATE TABLE MatchTag (Id VARCHAR2(36) PRIMARY KEY, Code VARCHAR2(20) NOT NULL UNIQUE, Label VARCHAR2(50) NOT NULL)";

    private readonly OracleContainerFixture _fixture;

    public UpsertMatchOnIntegrationTests(OracleContainerFixture fixture) => _fixture = fixture;

    [SkippableFact]
    public async Task InsertThenUpdateKeepsGeneratedKey()
    {
        Skip.IfNot(_fixture.IsAvailable, _fixture.SkipReason);
        await using var harness = await OracleTestHarness.CreateFromDdlAsync(_fixture.AdminConnectionString, Ddl, "matchon");
        await UpsertMatchOnScenarios.InsertThenUpdateKeepsGeneratedKeyAsync(harness.GetRequiredService<MatchPrefStore>());
    }

    [SkippableFact]
    public async Task NonReturningUpsertInsertsThenUpdates()
    {
        Skip.IfNot(_fixture.IsAvailable, _fixture.SkipReason);
        await using var harness = await OracleTestHarness.CreateFromDdlAsync(_fixture.AdminConnectionString, Ddl, "matchon");
        await UpsertMatchOnScenarios.NonReturningUpsertInsertsThenUpdatesAsync(harness.GetRequiredService<MatchPrefStore>());
    }

    [SkippableFact]
    public async Task AssignedKeyOfExistingRowDoesNotChange()
    {
        Skip.IfNot(_fixture.IsAvailable, _fixture.SkipReason);
        await using var harness = await OracleTestHarness.CreateFromDdlAsync(_fixture.AdminConnectionString, Ddl, "matchon");
        await UpsertMatchOnAssignedKeyScenarios.AssignedKeyOfExistingRowDoesNotChangeAsync(harness.GetRequiredService<MatchTagStore>());
    }

    // MERGE does not lock a missing row, so a parallel caller can lose with ORA-00001, as on a key
    // upsert. The table still ends with one row.
    [SkippableFact]
    public async Task ParallelUpsertsOfOneNaturalKeyEndInOneRowAndFailOnlyWithUniqueViolation()
    {
        Skip.IfNot(_fixture.IsAvailable, _fixture.SkipReason);
        await using var harness = await OracleTestHarness.CreateFromDdlAsync(_fixture.AdminConnectionString, Ddl, "matchon");
        var failures = await UpsertMatchOnScenarios.ParallelUpsertsOfOneNaturalKeyAsync(harness.GetRequiredService<MatchPrefStore>());

        Assert.All(failures, static failure => Assert.Equal(1, Assert.IsType<global::Oracle.ManagedDataAccess.Client.OracleException>(failure).Number));
    }
}
